  perform public.author_session((select id from public.athletes where slug='hope'),(select id from public.training_weeks where athlete_id=(select id from public.athletes where slug='hope') and week_number=15),'WED', 'Easy', 'Aerobic base. There is no floor — slower is never wrong.', date '2026-12-02', null, 5.0, 'mi', null, null, null,'[{"role": "work", "shape": "continuous", "position": 1, "distance": 5, "distanceUnit": "mi", "paceLowSeconds": 525}]'::jsonb, null);
  perform public.author_session((select id from public.athletes where slug='hope'),(select id from public.training_weeks where athlete_id=(select id from public.athletes where slug='hope') and week_number=15),'THU', 'Easy with strides', 'A little mechanical brightness. Relaxed, not fast.', date '2026-12-03', null, 4.5, 'mi', null, null, null,'[{"role": "work", "shape": "continuous", "position": 1, "distance": 4, "distanceUnit": "mi", "paceLowSeconds": 525}, {"role": "work", "shape": "repetitions", "position": 2, "durationSeconds": 20, "repeatCount": 4, "recoveryKind": "easy", "recoverySeconds": 60}]'::jsonb, null);
